typedef struct {
  Type *t;
  char *op;
  int lv;
  int ck;
  CVal cv;
  int bf, bitoff, hbytes;
} Val; /* bf: bit-field lvalue in a packed host of hbytes at op */
typedef struct Defer {
  Node *n;
  int err;
  Scope *s;
  char *cap;
} Defer;
typedef struct Res {
  Type *t;
  char *slot;
  int has;
  Type *ex;
  int collect;
} Res;
typedef struct Inl {
  Res *res;
  char *lx;
  int dbase, nret, allck, level;
  CVal ckv;
} Inl;
typedef struct Loop {
  char *label, *brk, *cont;
  Res *res;
  int dbase, kind, cont_used, brk_used;
  char *swslot, *swdisp;
  Type *swt;
  struct Loop *up;
} Loop;
typedef struct {
  int range;
  char *start;
  char *base;
  Type *et;
  char *len;
} Iter;

